// Reports are derived from current source and the completed browser evidence; no application mutation.
import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';
import {root,read,write} from '../db/lib.mjs';
const out=path.join(root,'audit/uiux'),load=n=>JSON.parse(read(path.join(out,n))),save=(n,v)=>write(path.join(out,n),v);
const browser=load('evidence/browser-metrics.json'),inv=load('FRONTEND_INVENTORY.json');assert.equal(browser.status,'PASS');assert.equal(load('evidence/preservation-cleanup.json').status,'PASS');
const src=file=>read(path.join(root,file));
const sourceLink=(file,needle)=>{const text=src(file),index=needle?text.indexOf(needle):0;assert.ok(index>=0,file+' '+needle);const line=text.slice(0,index).split('\n').length;return{file,line,link:`[${path.basename(file)}:${line}](../../${file}#L${line})`};};
const components=inv.componentFiles.filter(f=>f.file.endsWith('.jsx')).map(f=>({...f,exports:[...src(f.file).matchAll(/export\s+(?:default\s+)?(?:function|class)\s+(\w+)/g)].map(m=>m[1])}));
inv.componentFiles=components;inv.pageFiles=inv.pageFiles.filter(f=>f.file.endsWith('.jsx'));inv.componentExports=components.flatMap(f=>f.exports.map(name=>({name,file:f.file})));inv.routeScreens=20;inv.inspectedViews=browser.capturedViews;inv.responsiveMeasurements=browser.metrics.length;
inv.architecture={router:'BrowserRouter / Routes / nested AreaLayout + role/identity guards',state:'React local useState/useEffect/useRef/useCallback + AuthContext; authSession; no Redux/Zustand',api:'Thin fetch REST client; sessionStorage identity token, AbortController where used',css:'One global index.css; no CSS modules, utility/UI framework or styled-components',iconLibrary:'None in dependency/source inventory; text links/buttons; favicon.svg',typography:'Inter, system-ui, sans-serif declared; no bundled Inter/font-face; platform fallback possible',assets:'Local favicon; movie/cinema media URLs supplied by existing data; not replaced for screenshots',dialogs:'Browser window.confirm for selected Admin destructive actions; no custom modal/dialog component',responsive:'auto-fit/minmax/min/clamp/flex-wrap and two max-width:680px media blocks',businessInvariants:'R1 datetime, R2 payment/hold, R3 RBAC/scope, R5 validation, R7 edit hydration retained'};save('FRONTEND_INVENTORY.json',inv);
inv.sharedInfrastructureComponents=['AreaLayout','RequireAuth','RequireRole','AuthProvider'];
inv.totalSharedComponents=inv.componentExports.length+inv.sharedInfrastructureComponents.length;
inv.componentCountDefinition='21 exported components in components/ plus one shared layout, two guards and AuthProvider = 25. Page-local components, hooks and composition roots are excluded.';
save('FRONTEND_INVENTORY.json',inv);
const findings=[];
const finding=(id,p,title,confidence,area,observation,impact,recommendation,refs,shots=[])=>findings.push({id,priority:p,title,confidence,area,observation,impact,recommendation,source:refs.map(([f,n])=>sourceLink(f,n)),screenshots:shots.map(s=>'evidence/screenshots/'+s),category:'UIUX',implemented:false});
finding('UIUX-001','P2','Các class form/list/card dùng trong portal không có CSS tương ứng','PROVEN','Forms / consistency','catalog-form, catalog-list, catalog-card, order-summary được dùng nhưng không định nghĩa trong index.css. Ảnh Manager/Admin cho thấy label và native input nối ngang; Orders/Complaints thiếu surface card.','Khó quét field, action và từng bản ghi; visual language rời public catalog.','NORMALIZE style cho các class đang có, field spacing và control sizing; giữ toàn bộ handler/name/state/validation.',[['frontend/src/components/ManagerResourceForm.jsx','className="catalog-form"'],['frontend/src/index.css',':root']],['manager-1440.png','admin-users-390.png','complaints-390.png']);
finding('UIUX-002','P1','Manager xóa phòng/ghế và hủy suất không có xác nhận','PROVEN','Manager / destructive interaction','Manager gọi action(delete/cancel) trực tiếp; không có window.confirm. Admin có xác nhận trước xóa/hủy. Chưa thực thi hành động phá hủy để lấy ảnh.','Một click nhầm có thể xóa record đủ điều kiện hoặc hủy suất đã thanh toán, dẫn tới sự kiện bồi thường; SQL integrity không xác nhận ý định người dùng.','REFINE xác nhận ý định có tên phòng/ghế/suất và hậu quả theo policy hiện tại; không đổi điều kiện hủy, refund hoặc compensation.',[['frontend/src/pages/ManagerPortal.jsx','api.deleteRoom'],['frontend/src/pages/ManagerPortal.jsx','api.cancelManagerShowtime'],['frontend/src/pages/AdminPortal.jsx','window.confirm']],['manager-1440.png']);
finding('UIUX-003','P2','Movie Detail tràn ngang do select tên rạp tại 360px','PROVEN','Responsive','Ở 360px, scrollWidth=377; select Rạp chiếu có right=377 trong capture. Đây là page overflow, khác table scroll có chủ đích.','Bộ lọc rạp chạm/tràn mép màn hình nhỏ.','REFINE min-width:0 / max-width / box sizing cho filter select trong phạm vi component, dùng đúng palette.',[['frontend/src/components/ShowtimeBrowser.jsx','<select'],['frontend/src/index.css','.catalog-filters']],['movie-detail-390.png']);
finding('UIUX-004','P2','Eyebrow nhỏ thiếu tương phản trên nền sáng','PROVEN','Accessibility / color use','catalog-eyebrow dùng #8ca6e5, 12px/800; contrast 2.23:1 trên #f5f6fa, 2.41:1 trên white. Không áp kết luận này cho hero gradient.','Các nhãn KHÁM PHÁ/QUẢN LÝ RẠP khó đọc; thấp hơn chuẩn text thường.','NORMALIZE cách dùng màu: giữ palette; dùng màu chữ tối đã có cho eyebrow trên surface sáng, giữ variant hero phù hợp.',[['frontend/src/index.css','.catalog-eyebrow']],['home-1440.png','manager-1440.png']);
finding('UIUX-005','P2','Admin bảng auto-generate theo keys kỹ thuật','PROVEN','Admin / data UI','Object.keys(rows[0]) tạo header Nguoi Dung ID, Ho Ten, Danh Sach Dien Vien Json; formatApiValue stringify object. Movie có 16 cột, users 11 cột.','Đọc chậm, thông tin kỹ thuật lấn át nghiệp vụ và action cuối hàng.','NORMALIZE column descriptors/UI labels và ưu tiên cột; giữ keys/ID/API; chuyển nội dung dài sang detail disclosure.',[['frontend/src/pages/AdminPortal.jsx','Object.keys(rows[0])'],['frontend/src/utils/dateTime.js','JSON.stringify']],['admin-users-390.png','admin-movies-1440.png']);
finding('UIUX-006','P2','Bảng Admin có horizontal scroll nhưng chưa hỗ trợ định hướng hàng','PROVEN','Responsive / data density','Users table ~1256px và Movie ~1953px trong wrapper mobile ~343px. Scroll được containment; không coi đây là page broken. Action và key context nằm xa nhau, không sticky column/header.','Di chuyển ngang nhiều để đọc và thao tác; khó giữ đúng hàng trên mobile.','REFINE cột quan trọng/action/context và scroll affordance; đánh giá compact row/detail panel cho mobile. Không tự thêm server pagination.',[['frontend/src/index.css','.catalog-table-wrap'],['frontend/src/pages/AdminPortal.jsx','<tbody>']],['admin-users-390.png','admin-movies-390.png']);
finding('UIUX-007','P2','Manager workspace và Admin navigation quá dày cho công việc thường xuyên','PROVEN','IA / orientation','Manager hiện tất cả dashboard, room/seat/create/showtime/pricing/revenue trên một page. Admin có 18 nút phân hệ cùng cấp; 390px nhiều hàng nav trước nội dung.','Phải cuộn/đọc nhiều; primary action và công việc liên quan ít được nhóm.','REFINE grouping/section anchors/collapsible hoặc nav nhỏ theo task; giữ routes, grants, per-section lazy reads.',[['frontend/src/pages/AdminPortal.jsx','const sections'],['frontend/src/pages/ManagerPortal.jsx','function ManagerWorkspace']],['admin-users-390.png','manager-seats-390.png']);
finding('UIUX-008','P2','Form yêu cầu ID/CSV/JSON thay vì ngữ cảnh dễ hiểu','PROVEN','Admin / Manager form UX','Movie ID/Mã phòng/Mã vai trò/Mã rạp nhập số; genre IDs/permission IDs CSV; cast JSON textarea trong movie edit. Các enum Admin create như Loại sản phẩm/Loại giảm giá/Định dạng là text.','Nhân viên cần tra cứu/copy mã và biết giá trị enum/JSON trước khi hoàn tất form; lỗi đầu vào tăng.','REFINE entity lookup và enum options dựa trên nguồn đã có; NORMALIZE UI field labels; chỉ REPLACE editor JSON bằng field editor khi giữ nguyên payload cast.',[['frontend/src/utils/adminForms.js','genreIds'],['frontend/src/pages/AdminPortal.jsx','JSON (actorId, role)'],['frontend/src/utils/managerForms.js','Movie ID']],['admin-movie-edit-390.png','admin-promotions-390.png']);
finding('UIUX-009','P2','SeatMap đang là list flex-wrap, không giữ hình hàng ghế','PROVEN','Customer / booking','seat-grid flex-wrap đặt A1..A8/B1..B8 theo bề rộng; mobile thành hai cột. Không có grouping theo hàng hay hướng màn hình.','Không thể dựa hình trực quan để chọn vị trí; scroll dài trước checkout.','REPLACE hẹp renderer list-wrap bằng grouped logical rows có kiểm thử responsive. Dùng dữ liệu hàng/số có thật; không bịa lối đi/toạ độ vật lý. Giữ seat IDs, aria-pressed, disabled và onToggle.',[['frontend/src/components/SeatMap.jsx','seats.map'],['frontend/src/index.css','.seat-grid']],['booking-390.png']);
finding('UIUX-010','P2','Login không khôi phục intent/context quay lại','HIGH-CONFIDENCE','Customer / flow','RequireAuth truyền state.from; Login navigate theo role về / hoặc portal, không dùng from. Booking link đăng nhập không mang return intent. Selection/filter là local state.','Khách đang chọn phim/suất hoặc mở order phải tìm lại sau login/refresh; không phải lỗi authorization.','REFINE safe return navigation + context-preservation phù hợp trong phase sau; chỉ navigate tới target actor được phép.',[['frontend/src/routes/RequireAuth.jsx','state={{ from'],['frontend/src/pages/auth/Login.jsx','navigate(user.role'],['frontend/src/pages/BookingPreparation.jsx','to="/login"']]);
finding('UIUX-011','P2','Customer area và fallback 404 là màn gần như trống','PROVEN','Navigation / system states','/account render Customer area bằng Placeholder h2; fallback * chỉ h2 404, không AreaLayout/main/link thoát. Customer nav Khách hàng trỏ /account.','Người dùng tới một điểm đến thiếu định hướng, hoặc mắc ở 404 không có CTA recovery.','REFINE nội dung/links tới các flow hiện có (orders/profile/complaints/home), không thêm UC/API hoặc đổi route.',[['frontend/src/routes/index.jsx','protectedArea(ROLES.CUSTOMER'],['frontend/src/pages/Placeholder.jsx','return <h2>']],['account-390.png','not-found-390.png']);
finding('UIUX-012','P2','Customer complaint khó khám phá từ navigation','PROVEN','Customer / discoverability','Public customer header có Đơn của tôi/Hồ sơ/Khách hàng; /orders detail không link complaint; /account lại placeholder. /complaints tồn tại nhưng không có link trong những điểm này.','Khách cần biết URL hoặc điều hướng ngoài để gửi khiếu nại sau xem đơn.','REFINE link tới route complaint đã có từ các context phù hợp; giữ ownership/permission guards.',[['frontend/src/routes/index.jsx','label: \'Đơn của tôi\''],['frontend/src/pages/OrderDetail.jsx','Quay lại đơn của tôi']],['orders-390.png','order-detail-390.png']);
finding('UIUX-013','P2','Support success notice bị xóa trong refresh sau write','PROVEN (source)','CSKH / feedback','afterWrite setNotice(success) rồi await selectComplaint; selectComplaint setNotice(null). Việc save/status được R8 xác nhận thành công; UX message tồn tại rất ngắn.','Nhân viên có thể không nhận biết thao tác xong, dù history/status đã cập nhật.','REFINE lifecycle của success feedback qua refresh; giữ history event và API behavior.',[['frontend/src/pages/SupportPortal.jsx','const afterWrite'],['frontend/src/pages/SupportPortal.jsx','setNotice(null)']],['support-detail-390.png']);
finding('UIUX-014','P2','Admin/Support/image form không có pending/disabled write state nhất quán','HIGH-CONFIDENCE','Interaction / FUNCTIONAL-RISK','Admin submit, Support processing/status và CinemaImageManager không có write-busy guard/disabled submit; Auth/Complaint/Manager/Payment có.','Risk double-submit hoặc người dùng tưởng treo; duplicate processing events có thể hợp lệ về SQL nhưng dư về ý định. Không tái hiện duplicate write trong audit.','NORMALIZE UI pending feedback/idempotent click guard; không đổi SP hoặc payment retry policy. Ghi FUNCTIONAL-RISK riêng để kiểm tra affected flow trước implementation.',[['frontend/src/pages/AdminPortal.jsx','const submit'],['frontend/src/pages/SupportPortal.jsx','const submitProcessing'],['frontend/src/components/CinemaImageManager.jsx','const submit']]);
finding('UIUX-015','P2','Error chung chưa gắn với field/focus','PROVEN','Accessibility / forms','Real login401 có role=alert nhưng input không aria-invalid/aria-describedby trỏ error. Nhiều form báo lỗi chung cuối/ngoài form; Register password có helper association riêng là điểm tốt.','Khó xác định field cần sửa bằng keyboard/assistive tech; không có focus recovery được quy định.','NORMALIZE per-field error association/error summary/focus khi phù hợp; không thay R5 validation/error contract.',[['frontend/src/pages/auth/Login.jsx','role="alert"'],['frontend/src/components/ManagerResourceForm.jsx','{error &&'],['frontend/src/pages/auth/Register.jsx','password-byte-limit']],['login-390.png']);
finding('UIUX-016','P2','Landmark/navigation accessibility chưa đồng bộ','PROVEN','Accessibility / global','Forbidden có 2 main (nested AreaLayout); fallback404 không main; không skip link trong capture. Hầu hết nav không aria-label; table th không scope/caption.','Screen reader và keyboard phải quét lại header, khó phân vùng/nav/bảng.','NORMALIZE landmarks, skip link và table semantics có phạm vi; giữ router/actor guard.',[['frontend/src/pages/Forbidden.jsx','<main'],['frontend/src/layouts/AreaLayout.jsx','<main'],['frontend/src/pages/AdminPortal.jsx','<thead>']],['forbidden-390.png','not-found-390.png']);
finding('UIUX-017','P2','Booking/payment copy đưa chi tiết triển khai cho khách','PROVEN','Content / UX','Giá do Database/DB chốt; Payment method THE_NOI_DIA/THE_QUOC_TE; Home hiển thị SQL Server/database identity và hướng dẫn cấu hình. Simulated-payment disclosure là cần giữ.','Thông tin kỹ thuật cạnh tranh với nội dung khách cần để quyết định; payment label khó hiểu.','REFINE human labels/microcopy; giữ disclosure mô phỏng, server authoritative total, deadline và policy; health debug cần tách theo cách được duyệt, không đổi API.',[['frontend/src/pages/BookingPreparation.jsx','do Database'],['frontend/src/pages/PaymentPage.jsx','Database chốt'],['frontend/src/components/DatabaseHealth.jsx','SQL Server']],['home-1440.png','payment-390.png']);
finding('UIUX-018','P2','Long-form/data navigation không được giữ qua URL và thiếu quản lý draft','HIGH-CONFIDENCE','Admin / Support / Manager','Admin active tab/selected row, Support selected complaint/filters, Manager editing state là local state. Switch clears forms; không có dirty warning/URL selection; browser refresh về mặc định.','Mất context/draft khi chuyển phân hệ hoặc refresh; ảnh Admin create→edit ở phía trên list chưa có focus/scroll-to-editor.','REFINE context/draft policy nhẹ (không đổi path/API), keyboard/focus-to-edit và back/cancel predictability; không refactor router tùy ý.',[['frontend/src/pages/AdminPortal.jsx','const switchSection'],['frontend/src/pages/SupportPortal.jsx','useState(null)'],['frontend/src/pages/ManagerPortal.jsx','setEditing']],['admin-user-edit-390.png']);
finding('UIUX-019','P3','Style values lặp lại và thiếu token registry','PROVEN','CSS architecture','Không CSS custom properties; primary #273e82/borders/radii hardcode nhiều lần; hai @media(max-width:680px) riêng. !important có ở button text variants.','Thay đổi nhẹ sau này dễ mất đồng bộ; hiện chưa chứng minh specificity bug.','NORMALIZE token hóa đúng các giá trị hiện có và gộp media block khi thật cần; không đổi palette/CSS framework.',[['frontend/src/index.css',':root'],['frontend/src/index.css','!important']]);
finding('UIUX-020','P3','Typography/interaction polish chưa thành component contract','PROVEN','Visual consistency','Body16px line-height normal; portal native inputs dùng platform defaults. Không authored hover/focus rules; native focus auto1px vẫn nhìn thấy trong Chrome. Heading/nav lẫn Manager Portal/Dashboard/Movie ID với tiếng Việt.','Nhịp chữ/labels không đồng đều giữa auth/public/portal; không được kết luận toàn bộ focus invisible.','REFINE labels/type rhythm/hover-focus consistency trong palette hiện có; giữ native focus visible và required behavior.',[['frontend/src/index.css','font-family'],['frontend/src/pages/ManagerPortal.jsx','Manager Portal']],['manager-1440.png']);
finding('UIUX-021','P3','Currency formatting và UI markup lặp ở nhiều feature','PROVEN','Component architecture','Money format helper lặp trong các page/component; list/detail/action markup tương tự nhưng không có Button/FormField/StatusBadge shared. Admin ~'+src('frontend/src/pages/AdminPortal.jsx').split('\n').length+' dòng, Manager ~'+src('frontend/src/pages/ManagerPortal.jsx').split('\n').length+' dòng, coupling render/state/action.','Chi phí giữ consistency tăng; độ dài này không đủ lý do rewrite.','NORMALIZE các primitives nhỏ/formatter khi touched; KEEP typed forms/dateTime utilities; tách component có trách nhiệm rõ sau evidence.',[['frontend/src/pages/Orders.jsx','const money'],['frontend/src/pages/PaymentPage.jsx','const money'],['frontend/src/pages/AdminPortal.jsx','export default function']]);
finding('UIUX-022','P3','Small links/touch targets cần kiểm tra theo ngữ cảnh','PROVEN measurement; conformance unclaimed','Accessibility / responsive','DOM ghi nhiều link có chiều cao dưới24px; Manager row buttons khoảng27px so với primary40px. Một số link inline có thể thuộc exception; đo size không đủ để kết luận WCAG fail.','Tap precision và hierarchy action có thể cải thiện trên mobile; cần đo spacing/overlap theo từng target.','REFINE padding/spacing ở nav và action groups; kiểm tra spacing/inline exceptions trước gán lỗi chuẩn.',[['frontend/src/index.css','.area__header nav'],['frontend/src/pages/ManagerPortal.jsx','Sửa phòng']],['manager-seats-390.png']);
const counts=Object.fromEntries(['P0','P1','P2','P3'].map(p=>[p,findings.filter(f=>f.priority===p).length]));save('UIUX_FINDINGS.json',{auditOnly:true,counts,findings,functionalRisks:findings.filter(f=>f.id==='UIUX-014'),noFunctionalFix:true});
const findingsMD='# UI/UX findings\n\nAudit only. Severity là tác động thao tác, không đánh giá đẹp/xấu. Confidence PROVEN=source/DOM/ảnh cụ thể; HIGH-CONFIDENCE=source path chưa tái hiện đầy đủ hành vi người dùng. '+JSON.stringify(counts)+'. Không sửa production.\n\n'+findings.map(f=>`## ${f.id} — ${f.priority}: ${f.title}\n\n- Confidence: ${f.confidence}; khu vực: ${f.area}.\n- Evidence: ${f.observation}\n- Impact: ${f.impact}\n- Incremental proposal: ${f.recommendation}\n- Source: ${f.source.map(s=>s.link).join(', ')}.\n- Screens: ${f.screenshots.map(s=>`[${path.basename(s)}](${s})`).join(', ')||'Source trace / browser-metrics.json'}.\n`).join('\n');save('UIUX_FINDINGS.md',findingsMD);
